seq=[2,4,3,9,5,4,6,3,9]
grid=[[2,4,3],[3,6,9],[9,4,5]]
positions={c:[(r,k) for r,row in enumerate(grid) for k,v in enumerate(row) if v==c] for c in set(seq)}
paths=[[(0,0)]]
for c in seq[1:]:
    new=[]
    for p in paths:
        for cell in positions[c]:
            if cell not in p and abs(cell[0]-p[-1][0])+abs(cell[1]-p[-1][1])==1:
                new.append(p+[cell])
    paths=new
paths
